create table if not exists public.ciptur_catalogo_infracoes(
  codigo text primary key,
  codigo_normalizado text not null unique,
  descricao text not null,
  base_legal text,
  pontos smallint,
  gravidade text,
  valor numeric(12,2),
  valor_texto text not null,
  ativo boolean not null default true,
  fonte text not null default 'Tabela do código de infração fornecida pela CIPTUR',
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);

create table if not exists public.ciptur_autos_infracao(
  id uuid primary key default gen_random_uuid(),
  data_infracao date not null,
  codigo_infracao text not null references public.ciptur_catalogo_infracoes(codigo),
  unidade_id uuid not null references public.unidades(id),
  descricao_snapshot text not null,
  base_legal_snapshot text,
  pontos_snapshot smallint,
  gravidade_snapshot text,
  valor_snapshot numeric(12,2),
  valor_texto_snapshot text not null,
  criado_por uuid not null references auth.users(id),
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);

create index if not exists ciptur_autos_infracao_unidade_data_idx on public.ciptur_autos_infracao(unidade_id,data_infracao desc);
create index if not exists ciptur_autos_infracao_codigo_data_idx on public.ciptur_autos_infracao(codigo_infracao,data_infracao desc);

alter table public.ciptur_catalogo_infracoes enable row level security;
alter table public.ciptur_autos_infracao enable row level security;

revoke all on public.ciptur_catalogo_infracoes from anon;
revoke all on public.ciptur_autos_infracao from anon;
grant select on public.ciptur_catalogo_infracoes to authenticated;
grant select,insert,update,delete on public.ciptur_autos_infracao to authenticated;
grant all on public.ciptur_catalogo_infracoes,public.ciptur_autos_infracao to service_role;

drop policy if exists auth_ciptur_catalogo_select on public.ciptur_catalogo_infracoes;
create policy auth_ciptur_catalogo_select on public.ciptur_catalogo_infracoes
for select to authenticated using ((select private.usuario_ativo()));

drop policy if exists auth_ciptur_ai_select on public.ciptur_autos_infracao;
create policy auth_ciptur_ai_select on public.ciptur_autos_infracao
for select to authenticated using ((select private.usuario_ativo()) and private.pode_acessar_unidade(unidade_id));

drop policy if exists auth_ciptur_ai_insert on public.ciptur_autos_infracao;
create policy auth_ciptur_ai_insert on public.ciptur_autos_infracao
for insert to authenticated with check (
  (select private.pode_escrever_operacional())
  and unidade_id=(select private.unidade_atual())
  and exists(select 1 from public.unidades u where u.id=(select private.unidade_atual()) and u.sigla='CIPTUR' and u.ativo=true)
);

drop policy if exists auth_ciptur_ai_update on public.ciptur_autos_infracao;
create policy auth_ciptur_ai_update on public.ciptur_autos_infracao
for update to authenticated
using (
  unidade_id=(select private.unidade_atual())
  and exists(select 1 from public.unidades u where u.id=(select private.unidade_atual()) and u.sigla='CIPTUR' and u.ativo=true)
  and ((select private.pode_administrar_dados()) or ((select private.perfil_atual())='OPERADOR' and criado_por=(select auth.uid())))
)
with check (
  unidade_id=(select private.unidade_atual())
  and exists(select 1 from public.unidades u where u.id=(select private.unidade_atual()) and u.sigla='CIPTUR' and u.ativo=true)
  and ((select private.pode_administrar_dados()) or ((select private.perfil_atual())='OPERADOR' and criado_por=(select auth.uid())))
);

drop policy if exists auth_ciptur_ai_delete on public.ciptur_autos_infracao;
create policy auth_ciptur_ai_delete on public.ciptur_autos_infracao
for delete to authenticated
using (
  unidade_id=(select private.unidade_atual())
  and exists(select 1 from public.unidades u where u.id=(select private.unidade_atual()) and u.sigla='CIPTUR' and u.ativo=true)
  and (select private.pode_administrar_dados())
);

create or replace function private.preparar_ciptur_auto_infracao()
returns trigger language plpgsql security definer set search_path=''
as $$
declare
  v_unidade uuid;
  v_cat public.ciptur_catalogo_infracoes%rowtype;
begin
  if (select auth.uid()) is null then raise exception 'Sessão autenticada obrigatória.'; end if;
  if not private.pode_escrever_operacional() then raise exception 'Usuário sem permissão operacional para lançar A.I.'; end if;
  v_unidade:=private.unidade_atual();
  if not exists(select 1 from public.unidades u where u.id=v_unidade and u.sigla='CIPTUR' and u.ativo=true) then
    raise exception 'Autos de infração são exclusivos da CIPTUR.';
  end if;
  if tg_op='UPDATE' and new.unidade_id is distinct from old.unidade_id then raise exception 'Não é permitido transferir A.I. entre unidades.'; end if;
  select * into v_cat from public.ciptur_catalogo_infracoes c where c.codigo=new.codigo_infracao and c.ativo=true;
  if not found then raise exception 'Código de infração inválido ou inativo: %',new.codigo_infracao; end if;
  new.unidade_id:=v_unidade;
  if tg_op='INSERT' then new.criado_por:=(select auth.uid()); end if;
  new.descricao_snapshot:=v_cat.descricao;
  new.base_legal_snapshot:=v_cat.base_legal;
  new.pontos_snapshot:=v_cat.pontos;
  new.gravidade_snapshot:=v_cat.gravidade;
  new.valor_snapshot:=v_cat.valor;
  new.valor_texto_snapshot:=v_cat.valor_texto;
  new.atualizado_em:=now();
  return new;
end
$$;
revoke all on function private.preparar_ciptur_auto_infracao() from public,anon,authenticated;

drop trigger if exists trg_preparar_ciptur_auto_infracao on public.ciptur_autos_infracao;
create trigger trg_preparar_ciptur_auto_infracao
before insert or update of data_infracao,codigo_infracao,unidade_id
on public.ciptur_autos_infracao
for each row execute function private.preparar_ciptur_auto_infracao();

values('AUTOS_INFRACAO','Autos de Infração','Cadastro estatístico de autos de infração da CIPTUR.',true,35)
on conflict(codigo) do update set nome=excluded.nome,descricao=excluded.descricao,ativo=true,ordem=excluded.ordem;

select u.id,m.id,true from public.unidades u cross join public.modulos_sistema m
where u.sigla='CIPTUR' and m.codigo='AUTOS_INFRACAO'
on conflict(unidade_id,modulo_id) do update set ativo=true;

on conflict(codigo) do update set
 codigo_normalizado=excluded.codigo_normalizado,
 descricao=excluded.descricao,
 base_legal=excluded.base_legal,
 pontos=excluded.pontos,
 gravidade=excluded.gravidade,
 valor=excluded.valor,
 valor_texto=excluded.valor_texto,
 ativo=true,
 atualizado_em=now();
